ALTER TABLE public.trips ADD COLUMN a2e_room boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION trip_private.check_trip_length() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.end_date - NEW.start_date + 1 NOT BETWEEN 2 AND 30 AND NOT (NEW.a2e_room AND NEW.season_rule='a2c' AND NEW.kind='trip' AND NEW.end_date-NEW.start_date+1 BETWEEN 1 AND 3650) THEN RAISE EXCEPTION 'Trips can be 2 to 30 days long'; END IF; RETURN NEW; END $$;
DO $migration$ DECLARE def text; BEGIN SELECT pg_get_functiondef('trip_private.create_culture_a2e(text,text,text,text,text,text,date,integer,text,text,text[],integer,text,text,boolean)'::regprocedure) INTO def; def:=replace(def,'finale_at,game_start)', 'finale_at,game_start,a2e_room)'); def:=replace(def,'greatest(current_date,p_start-7)) RETURNING', 'greatest(current_date,p_start-7),true) RETURNING'); EXECUTE def; END $migration$;
ALTER TABLE public.trips ADD CONSTRAINT trips_a2e_length_check CHECK (NOT a2e_room OR (season_rule='a2c' AND end_date>=start_date AND end_date-start_date<3650));